package com.learnagent.skill;
import com.learnagent.agent.AgentExecutionTracker;import com.learnagent.analysis.AnalysisService;import java.util.*;import org.springframework.ai.tool.annotation.*;import org.springframework.stereotype.Component;
@Component public class AnalysisSkill{private final AnalysisService service;private final AgentExecutionTracker tracker;public AnalysisSkill(AnalysisService service,AgentExecutionTracker tracker){this.service=service;this.tracker=tracker;}@Tool(description="Read statistically identified weak knowledge points from real answer history.")public List<WeakPointResult> getWeakPoints(@ToolParam(description="Optional course ID; null means all courses",required=false)UUID courseId){return tracker.execute("Analysis Skill","getWeakPoints",()->service.weakPoints(courseId).stream().map(x->new WeakPointResult(x.knowledgePoint(),x.attemptCount(),x.correctCount(),x.wrongCount(),x.accuracy())).toList(),values->"Found "+values.size()+" weak points");}@Tool(description="Read current task and quiz learning statistics.")public StatisticsResult getLearningStatistics(@ToolParam(description="Optional course ID; null means all courses",required=false)UUID courseId){return tracker.execute("Analysis Skill","getLearningStatistics",()->{var x=service.statistics(courseId);return new StatisticsResult(x.totalQuizzes(),x.totalQuestionsAnswered(),x.correctAnswers(),x.overallAccuracy(),x.completedTasks(),x.pendingTasks(),x.weakPointCount());},x->"Loaded learning statistics");}public record WeakPointResult(String knowledgePoint,int attemptCount,int correctCount,int wrongCount,double accuracy){}public record StatisticsResult(long totalQuizzes,long totalQuestionsAnswered,int correctAnswers,double overallAccuracy,long completedTasks,long pendingTasks,int weakPointCount){}}
